const BACKUP_TABLES=['clientes','veiculos','ordens_servico','estoque','agendamentos','lancamentos_financeiros','sincronizacao'];
async function readAllTableRows(session,table){const rows=[];for(let offset=0;;offset+=1000){const page=await request(`/rest/v1/${table}?select=*&limit=1000&offset=${offset}`,{token:session.access_token});rows.push(...page);if(page.length<1000)break}return rows}
export async function createOperationalBackup(){if(currentEmail()!==OWNER_EMAIL)throw new Error('Somente o proprietário pode criar cópias de segurança.');const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');const entries=await Promise.all(BACKUP_TABLES.map(async table=>[table,await readAllTableRows(session,table)])),tables=Object.fromEntries(entries);return{format:'cortez-garage-operational-backup',version:1,projectRef:'pqldixrfvmkwkwbbysyl',createdAt:new Date().toISOString(),tables,counts:Object.fromEntries(entries.map(([table,rows])=>[table,rows.length]))}}
async function restoreRows(session,table,rows){for(let index=0;index<rows.length;index+=200)await request(`/rest/v1/${table}?on_conflict=id`,{token:session.access_token,method:'POST',prefer:'resolution=merge-duplicates,return=minimal',body:rows.slice(index,index+200)})}
