export async function restoreOperationalBackup(backup){if(currentEmail()!==OWNER_EMAIL)throw new Error('Somente o proprietário pode restaurar cópias de segurança.');if(backup?.format!=='cortez-garage-operational-backup'||backup?.version!==1||!backup.tables)throw new Error('Arquivo de backup inválido ou incompatível.');if(backup.projectRef&&backup.projectRef!=='pqldixrfvmkwkwbbysyl')throw new Error('Este backup pertence a outro projeto.');const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');for(const table of BACKUP_TABLES){const rows=backup.tables[table];if(!Array.isArray(rows))throw new Error(`O backup não contém a tabela ${table}.`)}for(const table of['clientes','veiculos','ordens_servico','estoque'])await restoreRows(session,table,backup.tables[table]);await restoreAppointments(session,backup.tables.agendamentos);for(const table of['lancamentos_financeiros','sincronizacao'])await restoreRows(session,table,backup.tables[table]);return{restored:Object.fromEntries(BACKUP_TABLES.map(table=>[table,backup.tables[table].length])),createdAt:backup.createdAt}}

export function getSession(){try{return JSON.parse(localStorage.getItem(SESSION_KEY)||'null')}catch{return null}}
export function getCurrentUser(){const user=getSession()?.user,metadata=user?.user_metadata||{};return{id:user?.id||'',name:metadata.name||metadata.nome||user?.email?.split('@')[0]||'Usuário',email:user?.email||'',deviceId:localStorage.getItem(DEVICE_KEY)||metadata.device_id||''}}
const currentEmail=()=>getCurrentUser().email.trim().toLowerCase();
export function canManageServices(){return hasPermission('manageValues')}
const defaultMechanicForEmail=email=>GUSTAVO_EMAILS.has(email)?'Gustavo':FABIO_EMAILS.has(email)?'Fabio':'';
export function agendaMechanicForCurrentUser(){const email=currentEmail(),user=getManagedUser(email);if(user?.active===false)return'';return clean(user?.agendaMechanic)||defaultMechanicForEmail(email)}
