const budgetHasItems=budget=>Boolean((budget?.parts||[]).length||(budget?.services||[]).length);
function repairedBudget(row,extras){const source=extras.budget&&typeof extras.budget==='object'?extras.budget:{},parts=Array.isArray(source.parts)?source.parts.filter(Boolean):[],services=Array.isArray(source.services)?source.services.filter(Boolean):[],partsValue=Number(row.valor_pecas)||0,labor=Number(row.mao_obra)||0;if(!parts.length&&partsValue>0)parts.push({description:clean(extras.parts)||'Peças e materiais — descrição anterior não recuperada',cost:partsValue,margin:0,quantity:1,value:partsValue,refused:false,recovered:true});if(!services.length&&labor>0)services.push({description:clean(extras.services)||'Mão de obra — descrição anterior não recuperada',mechanic:clean(row.mecanico),value:labor,refused:false,recovered:true});return{...source,parts,services,partsTotal:parts.filter(item=>!item.refused).reduce((sum,item)=>sum+Math.max(1,Number(item.quantity)||1)*Number(item.value||0),0),servicesTotal:services.filter(item=>!item.refused).reduce((sum,item)=>sum+Number(item.value||0),0)}}
function mapOrder(row,clients,vehicles){const extras=row.dados_extras||{},budget=repairedBudget(row,extras),client=clients.find(item=>item.id===row.cliente_id)||extras.client||{},vehicle=vehicles.find(item=>item.id===row.veiculo_id)||extras.vehicle||{},labor=Number(row.mao_obra)||Number(budget.servicesTotal)||0,partsValue=Number(row.valor_pecas)||Number(budget.partsTotal)||0,discount=Number(row.desconto)||0,total=Number(row.total)||Number(budget.total)||labor+partsValue-discount;return{id:row.id,number:String(row.numero).padStart(4,'0'),created:row.data_entrada,client,vehicle,complaint:row.reclamacao||'',diagnosis:row.diagnostico||'',notes:row.observacoes||'',damage:row.avarias||'',mechanic:row.mecanico||'',status:row.status,labor,partsValue,discount,total,advance:Number(extras.advance)||0,advancePayment:extras.advancePayment||'',advanceAt:extras.advanceAt||null,payment:row.pagamento||'',checklist:row.checklist||[],photos:row.fotos||[],signature:'',services:extras.services||'',parts:extras.parts||'',budget,technicalReport:extras.technicalReport||null,createdBy:extras.createdBy||null,updatedBy:extras.updatedBy||null,updatedAt:row.atualizado_em,deliveredAt:row.entregue_em||null}}
