const rowServiceKey=row=>{const client=clean(row.dados_extras?.client?.name).toLowerCase(),plate=clean(row.dados_extras?.vehicle?.plate).toLowerCase(),day=String(row.data_entrada||'').slice(0,10),complaint=clean(row.reclamacao).toLowerCase();return client&&plate&&day&&complaint?`${client}|${plate}|${day}|${complaint}`:null};
