async function readDatabase(token){const [clientRows,vehicleRows,orderRows]=await Promise.all([request('/rest/v1/clientes?select=*',{token}),request('/rest/v1/veiculos?select=*',{token}),request('/rest/v1/ordens_servico?select=*&order=numero.asc',{token})]);const clients=clientRows.map(mapClient),vehicles=vehicleRows.map(mapVehicle),orders=orderRows.map(row=>mapOrder(row,clients,vehicles));return{clients,vehicles,orders,counter:Math.max(0,...orders.map(order=>Number(order.number)||0))+1}}
async function upsert(token,table,rows,onConflict){if(!rows.length)return[];return request(`/rest/v1/${table}?on_conflict=${onConflict}`,{token,method:'POST',prefer:'resolution=merge-duplicates,return=representation',body:rows})}
async function writeDatabase(token,db){
  const actor=getCurrentUser(),audit={id:actor.id,name:actor.name,email:actor.email,deviceId:getDeviceId(),at:new Date().toISOString()};
  const clients=await upsert(token,'clientes',(db.clients||[]).map(item=>({id:uuid(item.id),nome:item.name,telefone:item.phone||null,cpf:item.cpf||null,endereco:item.address||null,email:item.email||null,observacoes:item.notes||null})), 'id');
  const clientIds=new Map(clients.map(row=>[clean(row.telefone)||clean(row.nome).toLowerCase(),row.id]));
  const migratedClientIds=new Map();
  for(const item of db.clients||[]){const oldId=item.id,key=clean(item.phone)||clean(item.name).toLowerCase(),newId=clientIds.get(key)||item.id;migratedClientIds.set(oldId,newId);item.id=newId}
  const resolveClientId=client=>migratedClientIds.get(client?.id)||clientIds.get(clean(client?.phone)||clean(client?.name).toLowerCase())||null;
  const vehicles=await upsert(token,'veiculos',(db.vehicles||[]).map(item=>({id:uuid(item.id),cliente_id:migratedClientIds.get(item.clientId)||null,placa:clean(item.plate).toUpperCase(),modelo:item.model,marca:item.brand||null,ano:String(item.year||'')||null,cor:item.color||null,quilometragem:Number(item.km)||null,combustivel:item.fuel||null})),'placa');
  const vehicleIds=new Map(vehicles.map(row=>[clean(row.placa).toUpperCase(),row.id]));
  const migratedVehicleIds=new Map();
  for(const item of db.vehicles||[]){const oldId=item.id,newId=vehicleIds.get(clean(item.plate).toUpperCase())||item.id;migratedVehicleIds.set(oldId,newId);item.clientId=migratedClientIds.get(item.clientId)||item.clientId;item.id=newId}
  const resolveVehicleId=vehicle=>migratedVehicleIds.get(vehicle?.id)||vehicleIds.get(clean(vehicle?.plate).toUpperCase())||null;
  const existingOrders=await request('/rest/v1/ordens_servico?select=id,numero,status,data_entrada,reclamacao,dados_extras',{token});
  const existingOrderIds=new Map(existingOrders.map(row=>[Number(row.numero),row.id]));
  const existingOrderRows=new Map(existingOrders.map(row=>[Number(row.numero),row]));
  const existingOrderNumbers=new Map(existingOrders.map(row=>[row.id,Number(row.numero)]));
  const existingOrderStatuses=new Map(existingOrders.map(row=>[Number(row.numero),row.status]));
  const existingOrderSignatures=new Map(existingOrders.map(row=>[rowServiceKey(row),row]).filter(([key])=>key));
  const usedOrderIds=new Set();
  const sourceOrders=unique(db.orders||[],orderKey);
  if(currentEmail()!==OWNER_EMAIL)for(const item of sourceOrders)if(item.status==='Pronto para entrega')item.status=existingOrderStatuses.get(Number(item.number))||'Em andamento';
  const rows=sourceOrders.map(item=>{const sameService=existingOrderSignatures.get(serviceKey(item)),numero=Number(sameService?.numero??item.number),savedId=sameService?.id||existingOrderIds.get(numero),candidate=isUuid(item.id)?item.id:null,conflicts=candidate&&existingOrderNumbers.has(candidate)&&existingOrderNumbers.get(candidate)!==numero;let id=savedId||(!conflicts&&!usedOrderIds.has(candidate)&&candidate)||crypto.randomUUID();while(usedOrderIds.has(id))id=crypto.randomUUID();usedOrderIds.add(id);item.number=String(numero).padStart(4,'0');const remoteBudget=(sameService||existingOrderRows.get(numero))?.dados_extras?.budget;return{id,numero,cliente_id:resolveClientId(item.client),veiculo_id:resolveVehicleId(item.vehicle),reclamacao:item.complaint||null,diagnostico:item.diagnosis||null,observacoes:item.notes||null,avarias:item.damage||null,mecanico:item.mechanic||null,status:item.status||'Aguardando diagnóstico',mao_obra:Number(item.labor)||0,valor_pecas:Number(item.partsValue)||0,desconto:Number(item.discount)||0,total:Number(item.total)||0,pagamento:item.payment||null,checklist:item.checklist||[],fotos:item.photos||[],dados_extras:{signature:item.signature||'',services:item.services||'',parts:item.parts||'',budget:protectedBudget(item,remoteBudget),technicalReport:item.technicalReport||null,advance:Number(item.advance)||0,advancePayment:item.advancePayment||'',advanceAt:item.advanceAt||null,client:{...item.client,id:resolveClientId(item.client)},vehicle:{...item.vehicle,id:resolveVehicleId(item.vehicle),clientId:resolveClientId(item.client)},createdBy:item.createdBy||audit,updatedBy:audit},data_entrada:item.created||new Date().toISOString()}});
  const orders=await upsert(token,'ordens_servico',rows,'numero');const orderIds=new Map(orders.map(row=>[String(row.numero).padStart(4,'0'),row.id]));for(const item of sourceOrders)item.id=orderIds.get(String(item.number).padStart(4,'0'))||item.id;db.orders=sourceOrders;
}

export async function syncSupabase(localDb){const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');let remote=await readDatabase(session.access_token);const firstMigration=!localStorage.getItem(MIGRATION_KEY);if(!firstMigration)return remote;if(!canManageServices()){localStorage.setItem(MIGRATION_KEY,new Date().toISOString());return remote}const localClients=unique(localDb.clients||[],item=>clean(item.phone)||clean(item.name).toLowerCase()),localVehicles=unique(localDb.vehicles||[],item=>clean(item.plate).toUpperCase()),localOrders=unique(localDb.orders||[],orderKey),merged={clients:merge(localClients,remote.clients||[],item=>clean(item.phone)||clean(item.name).toLowerCase()),vehicles:merge(localVehicles,remote.vehicles||[],item=>clean(item.plate).toUpperCase()),orders:merge(localOrders,remote.orders||[],orderKey),counter:Math.max(Number(localDb.counter||1),Number(remote.counter||1))};await writeDatabase(session.access_token,merged);localStorage.setItem(MIGRATION_KEY,new Date().toISOString());return readDatabase(session.access_token)}
