const stockKey=item=>clean(item.codigo||item.code).toLowerCase()||`${clean(item.descricao||item.description).toLowerCase()}|${clean(item.aplicacao||item.application).toLowerCase()}`;
async function stockMetadataConfig(session){const rows=await request('/rest/v1/sincronizacao?entidade=eq.configuracao&registro_id=eq.estoque-metadados&select=id,dados&limit=1',{token:session.access_token});return rows[0]||null}
const stockMetadataItems=row=>row?.dados?.items&&typeof row.dados.items==='object'?row.dados.items:{};
async function writeStockMetadataConfig(session,row,items){const body={origem:'app',entidade:'configuracao',registro_id:'estoque-metadados',dados:{items,updatedAt:new Date().toISOString()}};if(row)await request(`/rest/v1/sincronizacao?id=eq.${encodeURIComponent(row.id)}`,{token:session.access_token,method:'PATCH',prefer:'return=minimal',body});else await request('/rest/v1/sincronizacao',{token:session.access_token,method:'POST',prefer:'return=minimal',body})}
const mapStock=(row,metadata={})=>{const brand=clean(metadata.brand||row.aplicacao),value=Number(row.valor_unitario)||0,cost=Number(metadata.cost??value)||0,markup=Number(metadata.markup??(cost>0?Math.max(0,(value/cost-1)*100):0))||0;return{id:row.id,code:row.codigo||'',description:row.descricao,brand,supplier:clean(metadata.supplier),application:brand,quantity:Number(row.quantidade)||0,cost,markup,value,photo:row.foto||'',updatedAt:row.atualizado_em}};
export async function readStock(){const session=await refreshSession(),[rows,metadataRow]=await Promise.all([request('/rest/v1/estoque?select=*&order=quantidade.desc,descricao.asc',{token:session.access_token}),stockMetadataConfig(session)]),metadata=stockMetadataItems(metadataRow);return rows.filter(row=>clean(row.descricao)).map(row=>mapStock(row,metadata[row.id]))}
export async function saveStockItems(items,{absolute=false}={}){const session=await refreshSession(),[current,metadataRow]=await Promise.all([request('/rest/v1/estoque?select=*',{token:session.access_token}),stockMetadataConfig(session)]),byKey=new Map(current.map(row=>[stockKey(row),row])),metadata={...stockMetadataItems(metadataRow)},saved=[];for(const item of items){const key=stockKey(item);if(!key)continue;const found=(item.id&&current.find(row=>row.id===item.id))||byKey.get(key),previous=found?metadata[found.id]||{}:{},quantity=absolute?Number(item.quantity||0):Number(found?.quantidade||0)+Number(item.quantity||0),brand=clean(item.brand??item.application??previous.brand??found?.aplicacao),supplier=clean(item.supplier??previous.supplier),cost=Number(item.cost??previous.cost??found?.valor_unitario??0)||0,markup=Number(item.markup??previous.markup??0)||0,value=Number(item.value??cost*(1+markup/100))||0,body={codigo:clean(item.code)||null,descricao:clean(item.description),aplicacao:brand||null,quantidade:quantity,valor_unitario:value,foto:item.photo||found?.foto||null};let rows;if(found)rows=await request(`/rest/v1/estoque?id=eq.${found.id}`,{token:session.access_token,method:'PATCH',prefer:'return=representation',body});else rows=await request('/rest/v1/estoque',{token:session.access_token,method:'POST',prefer:'return=representation',body});const row=rows[0],details={brand,supplier,cost,markup};metadata[row.id]=details;byKey.set(stockKey(row),row);saved.push(mapStock(row,details))}await writeStockMetadataConfig(session,metadataRow,metadata);return saved}
