export async function consumeStockForOrder(order,selections=[]){const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');const movementId=encodeURIComponent(order.id),done=await request(`/rest/v1/sincronizacao?entidade=eq.estoque_saida&registro_id=eq.${movementId}&select=id&limit=1`,{token:session.access_token});if(done.length)return{alreadyProcessed:true,missing:[]};const rows=await request('/rest/v1/estoque?select=*',{token:session.access_token}),missing=[],used=[];for(const [index,part]of(order.budget?.parts||[]).entries()){if(part.refused)continue;const chosen=selections.find(item=>Number(item.partIndex)===index),code=clean(part.code).toLowerCase(),description=clean(part.description).toLowerCase(),found=chosen?rows.find(row=>row.id===chosen.stockId):rows.find(row=>(code&&clean(row.codigo).toLowerCase()===code)||clean(row.descricao).toLowerCase()===description),needed=Math.max(1,Number(part.quantity||1));if(!found||Number(found.quantidade||0)<needed){missing.push(part.description);continue}used.push({partIndex:index,stockId:found.id,description:part.description,quantity:needed,saleValue:Math.max(Number(found.valor_unitario||0),Number(part.value||0)),remaining:Number(found.quantidade||0)-needed})}if(missing.length)return{alreadyProcessed:false,missing};for(const item of used)await request(`/rest/v1/estoque?id=eq.${item.stockId}`,{token:session.access_token,method:'PATCH',prefer:'return=minimal',body:{quantidade:item.remaining,valor_unitario:item.saleValue}});await request('/rest/v1/sincronizacao',{token:session.access_token,method:'POST',prefer:'return=minimal',body:{origem:'app',entidade:'estoque_saida',registro_id:order.id,dados:{ordem:order.number,pecas:used.map(({remaining,...item})=>item),faltantes:[]}}});return{alreadyProcessed:false,missing:[]}}

const mapFinance=row=>({id:row.id,category:row.categoria,kind:row.movimento,description:row.descricao,amount:Number(row.valor)||0,dueDate:row.vencimento,status:row.status,mechanic:row.mecanico||'',paymentType:row.forma_pagamento||'',orderId:row.os_id||'',reference:row.referencia||'',weekStart:row.semana_inicio||'',createdAt:row.criado_em,updatedAt:row.atualizado_em});
const automaticCashExpense=description=>{const text=clean(description).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return /\bcompr\w*\b.*\bpecas?\b|\bpecas?\b.*\bcompr\w*\b/.test(text)||/\b(pagamento|pagar|pago|quitacao)\b.*\bboletos?\b|\bboletos?\b.*\b(pagamento|pagar|pago|quitacao)\b/.test(text)||/\b(?:pago|pagamento)\b.*\bluizinho\b|\bluizinho\b.*\b(?:pago|pagamento)\b/.test(text)||/\bcomiss(?:ao|oes)\b/.test(text)};
const financeText=value=>clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const isLuizinhoPayment=description=>{const text=financeText(description);return /\bluizinho\b/.test(text)&&/\b(?:pago|pagamento)\b/.test(text)};
function paidBillSupplier(description){const text=financeText(description),match=text.match(/\bpago\s+boletos?\s+(?:d[oa]\s+|de\s+)?(.+)$/)||text.match(/\bboletos?\s+pago\s+(?:d[oa]\s+|de\s+)?(.+)$/);return clean(match?.[1])}
async function duplicateFinanceRecord(session,record,kind,excludeId=''){const rows=await request(`/rest/v1/lancamentos_financeiros?select=id,descricao,valor,forma_pagamento&categoria=eq.${encodeURIComponent(record.category)}&movimento=eq.${encodeURIComponent(kind)}&vencimento=eq.${encodeURIComponent(record.dueDate)}`,{token:session.access_token});return rows.find(row=>row.id!==excludeId&&financeText(row.descricao)===financeText(record.description)&&Math.abs(Number(row.valor||0)-Number(record.amount||0))<.01&&financeText(row.forma_pagamento)===financeText(record.paymentType))}
async function matchingPayable(session,description,amount){const supplier=paidBillSupplier(description);if(!supplier)return null;const rows=await request('/rest/v1/lancamentos_financeiros?select=id,descricao,valor,vencimento&categoria=eq.Conta%20a%20pagar&status=neq.Realizado&order=vencimento.asc',{token:session.access_token}),matchTerm=term=>rows.filter(row=>{const payable=financeText(row.descricao);return payable.includes(term)||term.includes(payable)}),firstWord=supplier.split(' ')[0],fullMatches=matchTerm(supplier),matches=fullMatches.length?fullMatches:(firstWord.length>=3?matchTerm(firstWord):[]),sameAmount=matches.filter(row=>Math.abs(Number(row.valor||0)-Number(amount||0))<.01);if(sameAmount.length===1)return sameAmount[0];if(!sameAmount.length&&matches.length===1)return matches[0];return null}
export async function readFinance(){const session=await refreshSession(),rows=await request('/rest/v1/lancamentos_financeiros?select=*&order=vencimento.desc',{token:session.access_token});return rows.map(mapFinance)}
const commissionMechanic=description=>{const normalized=clean(description).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(!/\bcomiss(?:ao|oes)\b/.test(normalized))return'';const names={gustavo:'Gustavo',fabio:'Fabio',fabiano:'Fabiano',marcelino:'Marcelino',cortez:'Cortez'},key=Object.keys(names).find(name=>new RegExp(`\\b${name}\\b`).test(normalized));return names[key]||''};
async function archivePaidCommissions(session,description,amount){const mechanic=commissionMechanic(description);if(!mechanic)return;const pending=await request(`/rest/v1/lancamentos_financeiros?select=id,valor,semana_inicio,vencimento&categoria=eq.Comiss%C3%B5es&mecanico=ilike.${encodeURIComponent(`*${mechanic}*`)}&status=neq.Realizado&order=semana_inicio.asc,vencimento.asc`,{token:session.access_token}),weeks=new Map();for(const row of pending){const week=row.semana_inicio||row.vencimento;if(!weeks.has(week))weeks.set(week,[]);weeks.get(week).push(row)}let available=Number(amount)||0;const ids=[];for(const rows of weeks.values()){const total=rows.reduce((sum,row)=>sum+Number(row.valor||0),0);if(total>available+.01)break;available-=total;ids.push(...rows.map(row=>row.id))}if(ids.length)await request(`/rest/v1/lancamentos_financeiros?id=in.(${ids.join(',')})`,{token:session.access_token,method:'PATCH',prefer:'return=minimal',body:{status:'Realizado'}})}
export async function saveFinanceRecord(record){const session=await refreshSession();if(!session?.access_token)throw new Error('Sessão expirada');const kind=record.category==='Fluxo de caixa'&&automaticCashExpense(record.description)?'Saída':record.kind,duplicate=await duplicateFinanceRecord(session,record,kind);if(duplicate)throw new Error('Lançamento duplicado: já existe no mesmo dia, caixa, tipo, valor e descrição.');const payable=record.category==='Fluxo de caixa'&&kind==='Saída'?await matchingPayable(session,record.description,record.amount):null,reference=record.reference||(payable?`pagamento-conta-${payable.id}`:null),rows=await request('/rest/v1/lancamentos_financeiros',{token:session.access_token,method:'POST',prefer:'return=representation',body:{categoria:record.category,movimento:kind,descricao:record.description,valor:Number(record.amount),vencimento:record.dueDate,status:record.status||'Pendente',mecanico:record.mechanic||null,forma_pagamento:record.paymentType||null,os_id:record.orderId||null,referencia:reference,semana_inicio:record.weekStart||null}});if(record.category==='Fluxo de caixa'&&kind==='Saída')await archivePaidCommissions(session,record.description,record.amount);if(payable)await request(`/rest/v1/lancamentos_financeiros?id=eq.${encodeURIComponent(payable.id)}`,{token:session.access_token,method:'PATCH',prefer:'return=minimal',body:{status:'Realizado',valor:Number(record.amount),forma_pagamento:record.paymentType||null}});if(record.category==='Fluxo de caixa')await syncLuizinhoPayables(session);return{...mapFinance(rows[0]),autoSettledPayable:payable?payable.descricao:''}}
