export async function markFinanceDone(id){const session=await refreshSession(),rows=await request(`/rest/v1/lancamentos_financeiros?id=eq.${encodeURIComponent(id)}&select=*`,{token:session.access_token}),row=rows[0];if(!row)return;const receivedAt=dateOnly(new Date()),isReceivable=row.categoria==='Conta a receber',body=isReceivable?{status:'Realizado',vencimento:receivedAt,semana_inicio:mondayOf(new Date())}:{status:'Realizado'};await request(`/rest/v1/lancamentos_financeiros?id=eq.${encodeURIComponent(id)}`,{token:session.access_token,method:'PATCH',prefer:'return=minimal',body});if(!isReceivable||Number(row.valor||0)<=0)return;const reference=`recebimento-${row.id}`,existing=await request(`/rest/v1/lancamentos_financeiros?select=id&referencia=eq.${encodeURIComponent(reference)}&limit=1`,{token:session.access_token});if(existing.length)return;await request('/rest/v1/lancamentos_financeiros',{token:session.access_token,method:'POST',prefer:'return=minimal',body:{categoria:'Fluxo de caixa',movimento:'Entrada',descricao:`Recebimento ${row.descricao}`,valor:Number(row.valor),vencimento:receivedAt,status:'Realizado',mecanico:null,forma_pagamento:row.forma_pagamento||'Pagamento a prazo',os_id:row.os_id||null,referencia:reference,semana_inicio:mondayOf(new Date())}})}
