  Object.assign(order,{advance:amount,advancePayment:paymentType||'',advanceAt});
  const reference=`adiantamento-os-${order.id}`,existing=await request(`/rest/v1/lancamentos_financeiros?select=id&referencia=eq.${encodeURIComponent(reference)}&limit=1`,{token:session.access_token});
